-- GENERATED by theme/render.py — theme «Papel». Edit theme/templates/nvim/colors.lua or contracts/themes/papel.json and re-run it.
-- Neovim colourscheme "ryce", theme «Papel» (papel).
-- Run by ~/.config/nvim/colors/ryce.lua (apps/nvim) from the current theme's
-- directory, so `:colorscheme ryce` always means "the desktop's theme". It runs
-- standalone too: nvim --clean -c 'luafile themes/papel/nvim/colors.lua'.
--
-- The shell's colours, so code reads like the command line above it: functions
-- in the aqua slot (fish's commands), keywords violet (fish's keywords), strings
-- green, numbers and constants gold, types slot 4 (aqua in Origen, grey in
-- Grafito, kanagawa's crystal in Ola), imports and attributes the bright violet;
-- variables and punctuation stay text and grey. Each theme's 16 ANSI colours
-- set the flavour. The background is left to kitty (translucent bg1
-- under Hyprland's blur); floating surfaces are opaque bg2 so a picker never
-- shows code through it. Never the signal colour.

local c = {
  bg1 = "#23382f", bg2 = "#293f35", bg3 = "#31473d", line = "#485e54",
  fg0 = "#f0dbcb", fg1 = "#dbc4b3", fg2 = "#c0a999",
  pill = "#e2bf76", ink = "#182b23",
  ok = "#a2d496", warn = "#e6d271", err = "#ea86af",
  red = "#e783ac", green = "#98cb8d", yellow = "#e4c973", blue = "#8bbbdd",
  magenta = "#c89cd2", cyan = "#84c9c4", grey = "#8fa598",
  -- Text: slot 7 on a dark ground; on paper slot 7 is a mid grey, so prose takes the ink.
  white = ("dark" == "light") and "#f0dbcb" or "#dbc4b3",
  aqua = "#a0dbd6", violet = "#d8b1e1",
}

local ansi = {
  "#13261e", "#e783ac", "#98cb8d", "#e4c973", "#8bbbdd", "#c89cd2", "#84c9c4", "#dbc4b3",
  "#8fa598", "#f799be", "#afdda5", "#f0da8d", "#a5cdeb", "#d8b1e1", "#a0dbd6", "#f8ece0",
}

-- `a` at opacity `t` over the theme's ground, for tinted backgrounds (diffs,
-- diagnostics) that must stay as quiet as the ground.
local function mix(a, t)
  local out = "#"
  for i = 2, 6, 2 do
    local x, y = tonumber(a:sub(i, i + 1), 16), tonumber(c.bg1:sub(i, i + 1), 16)
    out = out .. string.format("%02x", math.floor(x * t + y * (1 - t) + 0.5))
  end
  return out
end

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end
vim.o.background = "dark"
vim.g.colors_name = "ryce"

for i, v in ipairs(ansi) do
  vim.g["terminal_color_" .. (i - 1)] = v
end

